        sceneId: "story_dialog_obj_story_015_c",
        pageIndex: 1,
        label: "[ 세렌 베일 ]",
        text: "기회는 보급 항로 하나다. 거점으로 가져가라. 나는 보더에 남는다.",
        labelEn: "[ Seren Vale ]",
