  "story_chapter_end_01": {
    id: "story_chapter_end_01",
    displayName: "챕터1 엔딩 시네마틱(대기)",
    triggerKey: "manual",
    triggerTargetId: null,
    triggerRepeat: "once",
    maxLinesPerPage: 4,
    completionPolicy: "return_hub_after_chapter_story",
    nextRoute: "/(game)/planet",
    skippable: true,
    typewriterSpeedMs: 72,
    fadeInEnabled: true,
    fadeInDurationMs: 700,
    fadeOutEnabled: true,
    fadeOutDurationMs: 600,
    pages: [
      {
        sceneId: "story_chapter_end_01",
        pageIndex: 0,
        label: "[ 은폐 ]",
        text: "라이트홀드는 보고서에서 지워졌고\n베가 함대는 전멸했으며\n살아남은 자들은 이름 없는 문을 세웠다.\n",
        labelEn: "[ Concealment ]",
        textEn: "Light Hold was wiped from the report,\nthe Vega fleet was lost,\nand those who lived raised a nameless door.\n",
        imageAssetKey: null,
        speakerNpcCaptainId: null,
        viewMode: "cinematic",
        textBoxPreset: "default",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      },
      {
        sceneId: "story_chapter_end_01",
        pageIndex: 1,
        label: "[ 동맹 ]",
        text: "깃발에는 진영이 없고\n장부에는 이름이 없다.\n그러나 문은 남아 있다.",
        labelEn: "[ Alliance ]",
        textEn: "The flag bears no faction\nand the ledger holds no names.\nYet the door remains.",
        imageAssetKey: null,
        speakerNpcCaptainId: null,
        viewMode: "cinematic",
        textBoxPreset: "default",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      },
      {
        sceneId: "story_chapter_end_01",
        pageIndex: 2,
        label: "[ 빚 ]",
        text: "코발은 침묵하고 소사는 타지 않는다.\n다시 버리지 말라는 조건만 남았다.\n",
        labelEn: "[ Debt ]",
        textEn: "Koval is silent. Sosa will not board.\nOnly the condition remains: do not abandon again.\n",
        imageAssetKey: null,
        speakerNpcCaptainId: null,
        viewMode: "cinematic",
        textBoxPreset: "default",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      },
      {
        sceneId: "story_chapter_end_01",
        pageIndex: 3,
        label: "[ 다음 ]",
        text: "은폐된 진실은 여기서 접히지만\n끝난 것은 아니다.\n다음 항로에서 다시 열린다.",
        labelEn: "[ Next ]",
        textEn: "The concealed truth folds here,\nbut it is not over.\nIt opens again on the next lane.",
        imageAssetKey: null,
        speakerNpcCaptainId: null,
        viewMode: "cinematic",
        textBoxPreset: "default",
        imageScalePct: 100,
        actionLabel: null,
        actionLabelEn: null,
      }
    ],
  },
